import pyomo.environ as pyo

DATA = {
    "foods": ["Lentils", "Rice", "Chicken", "Beef", "Tofu"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per unit of each food
    "cost": {
        "Lentils": 7,
        "Rice": 6,
        "Chicken": 6,
        "Beef": 10,
        "Tofu": 2,
    },
    # content[nutrient][food]
    "content": {
        "protein": {
            "Lentils": 13, "Rice": 2, "Chicken": 7, "Beef": 18, "Tofu": 12,
        },
        "carbs": {
            "Lentils": 21, "Rice": 30, "Chicken": 13, "Beef": 8, "Tofu": 28,
        },
        "calories": {
            "Lentils": 284, "Rice": 55, "Chicken": 276, "Beef": 204, "Tofu": 160,
        },
    },
    # minimum requirements per nutrient ("at least")
    "requirement": {
        "protein": 79,
        "carbs": 170,
        "calories": 1699,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    foods = list(d["foods"])
    nutrients = list(d["nutrients"])

    model.FOODS = pyo.Set(initialize=foods)
    model.NUTRIENTS = pyo.Set(initialize=nutrients)

    # Decision variables: amount of each food chosen (continuous, >= 0)
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals, bounds=(0, None))

    # Objective: minimise total cost
    model.obj = pyo.Objective(
        expr=sum(d["cost"][i] * model.x[i] for i in model.FOODS),
        sense=pyo.minimize,
    )

    # Nutrient requirement constraints: at least the specified amount
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.FOODS) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


